#!/bin/bash
# gateway EC2에서 nginx 설정 업데이트

aws ssm send-command \
  --targets "Key=tag:Project,Values=ants-camp" \
  --document-name "AWS-RunShellScript" \
  --parameters commands='[
    "echo  | base64 -d | sudo tee /etc/nginx/sites-enabled/ants-camp > /dev/null",
    "echo  | base64 -d | sudo tee /etc/nginx/sites-enabled/api-gateway.conf > /dev/null",
    "sudo nginx -t && sudo nginx -s reload && echo nginx reload OK || echo nginx reload FAILED"
  ]' \
  --region ap-northeast-2 \
  --output text \
  --query "Command.CommandId"
